348   static bool classof(const Value *V) {
349     unsigned Opcode;
350     if (auto *I = dyn_cast<Instruction>(V))
351       Opcode = I->getOpcode();
352     else
353       return false;
354 
355     switch (Opcode) {
356     case Instruction::FNeg:
357     case Instruction::FAdd:
358     case Instruction::FSub:
359     case Instruction::FMul:
360     case Instruction::FDiv:
361     case Instruction::FRem:
362     case Instruction::FPTrunc:
363     case Instruction::FPExt:
364     // FIXME: To clean up and correct the semantics of fast-math-flags, FCmp
365     //        should not be treated as a math op, but the other opcodes should.
366     //        This would make things consistent with Select/PHI (FP value type
367     //        determines whether they are math ops and, therefore, capable of
368     //        having fast-math-flags).
369     case Instruction::FCmp:
370       return true;
371     case Instruction::PHI:
372     case Instruction::Select:
373     case Instruction::Call: {
374       return isSupportedFloatingPointType(V->getType());
375     }
376     default:
377       return false;
378     }
379   }
