382 /// A helper template for defining operators for individual opcodes.
383 template<typename SuperClass, unsigned Opc>
384 class ConcreteOperator : public SuperClass {
385 public:
386   static bool classof(const Instruction *I) {
387     return I->getOpcode() == Opc;
